package dev.hryshyn.remanence.ui.collage

import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertTrue
import org.junit.Test
import kotlinx.coroutines.runBlocking

/**
 * T151 R7 differential — the **real Android** feasibility/cost matrix against
 * the frozen `ref_resolve.js` MATRIX.
 *
 * `v5_android_analysis_reference.txt` (generated by
 * `tasks/T151/evidence/ref_android_analysis.js` from the accepted T034
 * `03_infer.json` features) carries the real per-photo `CollageAnalysis` inputs.
 * `v5_resolve_reference.txt` carries the frozen `V4_CROP.crop` + `assignPhotos`
 * cost matrix per branch. This test builds the same branch plans in Kotlin, runs
 * [AndroidCollageCropMatrixSource] (the port of the frozen crop ladder + cost)
 * over those real analyses, and compares every (slot, photo) cell: feasibility
 * exact, cost within 1e-4.
 *
 * Synthetic fixtures (empty detector fields) are included; they exercise the
 * aperture/branch math only, exactly as the T153 packet labels them.
 */
class AndroidMatrixFrozenDifferentialTest {

    private val stub = FrozenGrammarPlans.LINE_HEIGHT_STUB
    private val costTol = 1e-4

    // ------------------------------------------------------------- analysis fixture

    private class AnalysisBuilder(val fixtureId: String, val photoId: String, val width: Int, val height: Int, val grid: Int) {
        val faces = ArrayList<AnalysisFace>()
        val objects = ArrayList<AnalysisObject>()
        val regions = ArrayList<AnalysisProtectedRegion>()
        val maps = HashMap<String, DoubleArray>()
        fun build(): CollageAnalysis = CollageAnalysis(
            width = width,
            height = height,
            faces = faces,
            objects = objects,
            protectedRegions = regions,
            importance = maps.getValue("importance"),
            baselineField = maps.getValue("baselineField"),
            objectField = maps.getValue("objectField"),
            saliency = maps.getValue("saliency"),
            edgeEnergy = maps.getValue("edgeEnergy"),
            structureField = maps.getValue("structureField"),
            gridSize = grid,
        )
    }

    private fun analyses(): Map<String, CollageAnalysis> {
        val text = requireNotNull(javaClass.getResource("/collage/v5_android_analysis_reference.txt")) {
            "missing android analysis reference"
        }.readText()
        val out = HashMap<String, CollageAnalysis>()
        var b: AnalysisBuilder? = null
        fun flush() {
            val cur = b ?: return
            out["${cur.fixtureId}|${cur.photoId}"] = cur.build()
        }
        for (raw in text.lineSequence()) {
            if (raw.isBlank() || raw.startsWith("#")) continue
            val f = raw.trimEnd('\r').split('\t')
            when (f[0]) {
                "A" -> {
                    flush()
                    b = AnalysisBuilder(f[1], f[2], f[3].toInt(), f[4].toInt(), f[5].toInt())
                }
                "F" -> b!!.faces += AnalysisFace(NormBox(f[3].toDouble(), f[4].toDouble(), f[5].toDouble(), f[6].toDouble()), f[7].toDouble())
                "O" -> b!!.objects += AnalysisObject(NormBox(f[3].toDouble(), f[4].toDouble(), f[5].toDouble(), f[6].toDouble()), f[7].toDouble(), f[8].toInt())
                "R" -> b!!.regions += AnalysisProtectedRegion(f[3], NormBox(f[4].toDouble(), f[5].toDouble(), f[6].toDouble(), f[7].toDouble()), f[8].toDouble(), f[9] == "1")
                "M" -> b!!.maps[f[3]] = f[4].split(',').map { it.toDouble() }.toDoubleArray()
            }
        }
        flush()
        return out
    }

    // --------------------------------------------------------------- resolve fixture

    private class PhotoRow(val id: String, val width: Int, val height: Int, val hasFace: Boolean)

    private class GrammarRef(val gid: Int) {
        var applicable = false
        val matrices = HashMap<Int, List<List<Double?>>>()
    }

    private class FixtureRef(val id: String, val note: Boolean, val music: Boolean) {
        val photoOrder = ArrayList<PhotoRow>()
        var grammar: GrammarRef? = null
        val grammars = LinkedHashMap<Int, GrammarRef>()
    }

    private fun resolveFixtures(): List<FixtureRef> {
        val text = requireNotNull(javaClass.getResource("/collage/v5_resolve_reference.txt")) {
            "missing resolve reference"
        }.readText()
        val out = ArrayList<FixtureRef>()
        var cur: FixtureRef? = null
        for (raw in text.lineSequence()) {
            if (raw.isBlank() || raw.startsWith("#")) continue
            val f = raw.trimEnd('\r').split('\t')
            when (f[0]) {
                "FIXTURE" -> {
                    cur = FixtureRef(f[1], f[3] == "1", f[4] == "1")
                    out += cur
                }
                "PHOTO" -> cur!!.photoOrder += PhotoRow(f[1], f[2].toInt(), f[3].toInt(), f[4] == "1")
                "GRAMMAR" -> {
                    val g = GrammarRef(f[1].toInt())
                    g.applicable = f[2] == "1"
                    cur!!.grammar = g
                    cur!!.grammars[g.gid] = g
                }
                "MATRIX" -> {
                    val g = cur!!.grammar!!
                    val n = cur!!.photoOrder.size
                    val matrix = f[2].split(';').map { row ->
                        val cells = MutableList<Double?>(n) { null }
                        if (row.isNotEmpty()) {
                            for (entry in row.split('|')) {
                                val p = entry.split(',')
                                if (p[1] == "1") cells[p[0].toInt()] = p[2].toDouble()
                            }
                        }
                        cells
                    }
                    g.matrices[f[1].toInt()] = matrix
                }
            }
        }
        return out
    }

    @Test
    fun androidMatrixMatchesFrozenV4CropAndAssignPhotosCostOnRealFeatures() = runBlocking {
        val analyses = analyses()
        val android = AndroidCollageCropMatrixSource()
        var compared = 0
        var feasible = 0

        for (fx in resolveFixtures()) {
            val matrixPhotos = fx.photoOrder.map { row ->
                CropMatrixPhoto(row.id, row.width, row.height, analyses["${fx.id}|${row.id}"])
            }
            // The shared analysis is authoritative only if every photo carries it.
            assertEquals(
                "analysis fixture must cover every photo of ${fx.id}",
                fx.photoOrder.size,
                matrixPhotos.count { it.analysis != null },
            )
            val inputPhotos = fx.photoOrder.map { row ->
                FrozenGrammarPlans.Photo(row.id, row.width.toDouble(), row.height.toDouble(), row.hasFace)
            }
            val d = FrozenGrammarPlans.Input(
                id = fx.id,
                sender = "T151",
                photos = inputPhotos,
                note = if (fx.note) "note" else null,
                music = if (fx.music) FrozenGrammarPlans.MusicInput(artwork = false) else null,
            )
            val plansByGrammar = LinkedHashMap<Int, List<FrozenGrammarPlans.Plan>>()
            val requests = LinkedHashSet<CropMatrixRequest>()
            for ((gid, g) in fx.grammars) {
                if (!g.applicable) continue
                val def = FrozenGrammarPlans.def(gid)
                val plans = FrozenGrammarPlans.plans(d, def, FrozenGrammarPlans.noteState(d, def, stub), stub)
                plansByGrammar[gid] = plans
                for (plan in plans) for (tile in plan.tiles) for (photo in matrixPhotos) {
                    requests += CropMatrixRequest(photo.contentId, tile.rect.w, tile.rect.h, tile.shape, tile.zooms, tile.assignmentRole)
                }
            }
            val cells = android.matrix(matrixPhotos, requests.toList())
            assertNotNull("real Android matrix must be available for ${fx.id}", cells)

            for ((gid, plans) in plansByGrammar) {
                val expectedMatrices = fx.grammars.getValue(gid).matrices
                plans.forEachIndexed { index, plan ->
                    val expected = requireNotNull(expectedMatrices[index]) { "missing frozen MATRIX ${fx.id} g$gid #$index" }
                    plan.tiles.forEachIndexed { slot, tile ->
                        matrixPhotos.forEachIndexed { j, photo ->
                            val request = CropMatrixRequest(photo.contentId, tile.rect.w, tile.rect.h, tile.shape, tile.zooms, tile.assignmentRole)
                            val cell = requireNotNull(cells!![request]) { "missing android cell ${fx.id} g$gid #$index slot$slot photo$j" }
                            val expCost = expected[slot][j]
                            val label = "${fx.id} g$gid #$index ${plan.branch} slot$slot photo$j"
                            assertEquals("feasibility ($label)", expCost != null, cell.feasible)
                            if (expCost != null) {
                                feasible++
                                assertNotNull("cost present ($label)", cell.cost)
                                assertTrue(
                                    "cost ($label) expected=$expCost actual=${cell.cost}",
                                    Math.abs(expCost - requireNotNull(cell.cost)) <= costTol,
                                )
                            }
                            compared++
                        }
                    }
                }
            }
        }
        assertTrue("matrix differential must compare many cells, got $compared", compared > 1000)
        assertTrue("must include feasible cells, got $feasible", feasible > 100)
    }
}
